function UIBattlingEatCard:ActionOnClickAreaSkillCard(pointerData)
    local vec2 = UIBattlingTools.ScreenPointToLocalPointInRectangle(pointerData.position, self.Root_SkillCardPool, UIBattlingCtrlMgr:GetInstance():GetUICamera())
    local battlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
    local skillPool = battlingDialog.luaTableDialogSkillPool
    local skillLocal = skillPool:GetPosIsOverSkillCardLocal(vec2)
    
    --- 中断条件
    if isNull(skillLocal) then return end
    local lbSkillCard = skillLocal.luaBehaviour
    if isNull(lbSkillCard) then return end
    local skillCard = lbSkillCard.Env
    if isNull(skillCard) then return end
    local skillCardOrigin = SkillPoolOperationMgr.teSkillCardOrigin
    if skillCard == skillCardOrigin then return end
    local conditionCannotEat = skillCard.isSPSkill
    if conditionCannotEat then return end

    --- 使用卡牌信息(包括删除卡牌信息)发送给逻辑
    local skillCardPosData = { skillCardOrigin.curTransArrLinePos, skillCardOrigin.curTransArrLine }
    -- print("->UIBattlingEatCard:ActionOnClickAreaSkillCard:", table.dump(skillCardPosData))
    local skillCardParams = {skillCard.curTransArrLinePos, skillCard.curTransArrLine }
    local data2Logic = { pos = skillCardPosData, params = skillCardParams }

    xTry(function()
        local _skillCardData = skillCardOrigin.skillCardData
        local _skillCardId = _skillCardData.skillId
        local _skillCardDConfigData = UIBattlingTools.GetSkillCardInfoByTwoParam(_skillCardId)
        local skillClickType = _skillCardDConfigData.clickType --技能点选规则（1、友方；2、敌方；3、全体；4、自身）
        local isEveryone = _skillCardDConfigData.isEveryone --是否无需点选（0、需点选；1、不需点选）
        local conditionNeed2FillAttackTarget = not checkBool(skillClickType == 1 and (not isEveryone))
        if conditionNeed2FillAttackTarget then
            battlingDialog = UIBattlingCtrlMgr:GetInstance().tableBattlingDialog
            if battlingDialog and (not isNull(battlingDialog.curAttTargetId)) then
                data2Logic.targetId = checkNumber(battlingDialog.curAttTargetId)
            end
        end
        -- print("->UIBattlingEatCard:ActionOnClickAreaSkillCard:", conditionNeed2FillAttackTarget, table.dump(checkTable(data2Logic)))
    end)
    
    Events.Broadcast(Constants.EventNames.BattleInputUse, data2Logic)
    ---关闭页面
    UIModule.CloseDialog(self.controller)
end

------------ Function ------------

return UIBattlingEatCard